import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.BitSet;
import java.util.Objects;

public final class CronExpression {

    private final BitSet minutes;   // 0-59
    private final BitSet hours;     // 0-23
    private final BitSet dom;       // 1-31
    private final BitSet months;    // 1-12
    private final BitSet dows;      // 0-6 (0=Sunday, 1=Monday, ..., 6=Saturday)

    private CronExpression(BitSet minutes, BitSet hours, BitSet dom, BitSet months, BitSet dows) {
        this.minutes = minutes;
        this.hours = hours;
        this.dom = dom;
        this.months = months;
        this.dows = dows;
    }

    public static CronExpression parse(String expr) {
        Objects.requireNonNull(expr, "expr must not be null");
        String[] parts = expr.trim().split("\\s+");
        if (parts.length != 5) {
            throw new IllegalArgumentException("Invalid cron expression: expected 5 fields but got " + parts.length);
        }

        BitSet minutes = parseField(parts[0], 0, 59, "minute", false);
        BitSet hours = parseField(parts[1], 0, 23, "hour", false);
        BitSet dom = parseField(parts[2], 1, 31, "day-of-month", false);
        BitSet months = parseField(parts[3], 1, 12, "month", false);
        BitSet dows = parseField(parts[4], 0, 7, "day-of-week", true); // allow 7 as Sunday alias

        // normalize dow: map 7 -> 0
        if (dows.get(7)) {
            dows.set(0);
            dows.clear(7);
        }
        ensureNonEmpty(minutes, "minute");
        ensureNonEmpty(hours, "hour");
        ensureNonEmpty(dom, "day-of-month");
        ensureNonEmpty(months, "month");
        ensureNonEmpty(dows, "day-of-week");

        return new CronExpression(minutes, hours, dom, months, dows);
    }

    public ZonedDateTime next(ZonedDateTime after) {
        Objects.requireNonNull(after, "after must not be null");
        ZoneId utc = ZoneOffset.UTC;
        // Work in UTC and at minute precision; strictly after -> start from next minute boundary
        LocalDateTime t = after.withZoneSameInstant(utc).truncatedTo(ChronoUnit.MINUTES).plusMinutes(1).toLocalDateTime();

        // Safety net: limit search to 10 years of minutes
        LocalDateTime limit = t.plusYears(10);

        while (!t.isAfter(limit)) {
            // Month check/adjust
            int month = t.getMonthValue();
            if (!months.get(month)) {
                int nextMon = nextOrFirst(months, 1, 12, month);
                if (nextMon > month) {
                    t = t.withMonth(nextMon).withDayOfMonth(1).withHour(0).withMinute(0);
                } else {
                    t = t.plusYears(1).withMonth(nextMon).withDayOfMonth(1).withHour(0).withMinute(0);
                }
                continue;
            }

            // Day check/adjust (OR semantics between day-of-month and day-of-week)
            if (!dayMatches(t)) {
                t = t.plusDays(1).withHour(0).withMinute(0);
                continue;
            }

            // Hour check/adjust
            int hour = t.getHour();
            if (!hours.get(hour)) {
                int nextHour = nextOrFirst(hours, 0, 23, hour);
                if (nextHour > hour) {
                    t = t.withHour(nextHour).withMinute(0);
                } else {
                    t = t.plusDays(1).withHour(nextHour).withMinute(0);
                }
                continue;
            }

            // Minute check/adjust
            int minute = t.getMinute();
            if (!minutes.get(minute)) {
                int nextMinute = nextOrFirst(minutes, 0, 59, minute);
                if (nextMinute > minute) {
                    t = t.withMinute(nextMinute);
                } else {
                    t = t.plusHours(1).withMinute(nextMinute);
                }
                continue;
            }

            // All fields match
            return ZonedDateTime.of(t, utc);
        }

        throw new IllegalStateException("No matching time found within 10 years for cron expression");
    }

    private boolean dayMatches(LocalDateTime t) {
        int day = t.getDayOfMonth();
        int maxDom = t.toLocalDate().lengthOfMonth();
        boolean domOk = day <= maxDom && dom.get(day);

        int javaDow = t.getDayOfWeek().getValue(); // 1=Mon .. 7=Sun
        int cronDow = javaDow % 7; // 0=Sun, 1=Mon, .., 6=Sat
        boolean dowOk = dows.get(cronDow);

        return domOk || dowOk;
    }

    private static int nextOrFirst(BitSet set, int min, int max, int value) {
        int n = set.nextSetBit(value);
        if (n >= min && n <= max) {
            return n;
        }
        int first = set.nextSetBit(min);
        if (first < 0 || first > max) {
            throw new IllegalArgumentException("Empty field set unexpectedly");
        }
        return first;
    }

    private static void ensureNonEmpty(BitSet bs, String fieldName) {
        if (bs.isEmpty()) {
            throw new IllegalArgumentException("No values allowed for field: " + fieldName);
        }
    }

    private static BitSet parseField(String text, int min, int maxInclusive, String fieldName, boolean allowDowSeven) {
        BitSet result = new BitSet(maxInclusive + 1);
        String[] items = text.split(",");
        for (String raw : items) {
            String item = raw.trim();
            if (item.isEmpty()) {
                throw new IllegalArgumentException("Empty token in " + fieldName + " field");
            }

            String rangePart = item;
            Integer step = null;

            int slashIdx = item.indexOf('/');
            if (slashIdx >= 0) {
                rangePart = item.substring(0, slashIdx).trim();
                String stepStr = item.substring(slashIdx + 1).trim();
                if (stepStr.isEmpty()) {
                    throw new IllegalArgumentException("Missing step value in " + fieldName + " field: " + item);
                }
                try {
                    step = Integer.parseInt(stepStr);
                } catch (NumberFormatException ex) {
                    throw new IllegalArgumentException("Invalid step '" + stepStr + "' in " + fieldName + " field", ex);
                }
                if (step <= 0) {
                    throw new IllegalArgumentException("Step must be positive in " + fieldName + " field: " + item);
                }
            }

            int from, to;
            if (rangePart.equals("*")) {
                from = min;
                to = maxInclusive;
            } else if (rangePart.contains("-")) {
                String[] ab = rangePart.split("-", 2);
                if (ab.length != 2 || ab[0].isEmpty() || ab[1].isEmpty()) {
                    throw new IllegalArgumentException("Invalid range '" + rangePart + "' in " + fieldName + " field");
                }
                int a = parseNumber(fieldName, ab[0], min, maxInclusive, allowDowSeven);
                int b = parseNumber(fieldName, ab[1], min, maxInclusive, allowDowSeven);
                if (fieldName.equals("day-of-week")) {
                    if (a == 7) a = 0;
                    if (b == 7) b = 0;
                }
                if (a > b) {
                    throw new IllegalArgumentException("Range start > end in " + fieldName + " field: " + rangePart);
                }
                from = a;
                to = b;
            } else {
                // single number or n/step (treated as n..max)
                int n = parseNumber(fieldName, rangePart.isEmpty() ? "*" : rangePart, min, maxInclusive, allowDowSeven);
                if (fieldName.equals("day-of-week") && n == 7) n = 0;
                from = n;
                to = (slashIdx >= 0 && !rangePart.equals("*")) ? maxInclusive : n;
            }

            if (step == null) {
                step = 1;
            }

            for (int v = from; v <= to; v += step) {
                result.set(v);
            }
        }
        // Clip invalid bits (e.g., in dow if user provided 7 we normalized above)
        result.clear(0, min);
        if (maxInclusive + 1 < result.size()) {
            result.clear(maxInclusive + 1, result.size());
        }
        return result;
    }

    private static int parseNumber(String fieldName, String s, int min, int maxInclusive, boolean allowDowSeven) {
        if (s.equals("*")) {
            return min; // handled by caller as a range
        }
        int n;
        try {
            n = Integer.parseInt(s);
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("Invalid number '" + s + "' in " + fieldName + " field", ex);
        }
        if (fieldName.equals("day-of-week") && allowDowSeven) {
            if (n == 7) {
                // allowed alias for Sunday; normalize later
                return 7;
            }
        }
        if (n < min || n > maxInclusive) {
            String range = min + "-" + maxInclusive + (fieldName.equals("day-of-week") && allowDowSeven ? " (7 allowed as Sunday)" : "");
            throw new IllegalArgumentException("Value out of range for " + fieldName + ": " + n + " (allowed " + range + ")");
        }
        return n;
    }
}

