import org.junit.jupiter.api.Test;

import java.time.ZoneOffset;
import java.time.ZonedDateTime;

import static org.junit.jupiter.api.Assertions.*;

public class CronExpressionTest {

    @Test
    void testEveryMinute() {
        CronExpression c = CronExpression.parse("* * * * *");
        ZonedDateTime after = ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 1, 1, 0, 1, 0, 0, ZoneOffset.UTC), next);
    }

    @Test
    void testStepMinutes() {
        CronExpression c = CronExpression.parse("*/15 * * * *");
        ZonedDateTime after = ZonedDateTime.of(2024, 1, 1, 12, 7, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 1, 1, 12, 15, 0, 0, ZoneOffset.UTC), next);

        ZonedDateTime afterExact = ZonedDateTime.of(2024, 1, 1, 12, 0, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next2 = c.next(afterExact);
        assertEquals(ZonedDateTime.of(2024, 1, 1, 12, 15, 0, 0, ZoneOffset.UTC), next2);
    }

    @Test
    void testNewYearMidnight() {
        CronExpression c = CronExpression.parse("0 0 1 1 *");
        // 1. From last minute of the year
        ZonedDateTime after = ZonedDateTime.of(2023, 12, 31, 23, 59, 59, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC), next);

        // 2. Exactly at fire time -> strictly after means next year
        ZonedDateTime atFire = ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next2 = c.next(atFire);
        assertEquals(ZonedDateTime.of(2025, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC), next2);
    }

    @Test
    void testWeekdaysAtNoon() {
        CronExpression c = CronExpression.parse("0 12 * * 1-5"); // Monday-Friday, noon
        // Friday 2024-08-16 11:59 -> same day at 12:00
        ZonedDateTime after = ZonedDateTime.of(2024, 8, 16, 11, 59, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 8, 16, 12, 0, 0, 0, ZoneOffset.UTC), next);

        // Exactly at Friday 12:00 -> next Monday 12:00
        ZonedDateTime atFire = ZonedDateTime.of(2024, 8, 16, 12, 0, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next2 = c.next(atFire);
        assertEquals(ZonedDateTime.of(2024, 8, 19, 12, 0, 0, 0, ZoneOffset.UTC), next2);
    }

    @Test
    void testFeb29() {
        CronExpression c = CronExpression.parse("0 0 29 2 *");
        ZonedDateTime after = ZonedDateTime.of(2021, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 2, 29, 0, 0, 0, 0, ZoneOffset.UTC), next);
    }

    @Test
    void testOrSemanticsDomDow() {
        // minutes */10, hours 9-10, day-of-month 1 or 15, months 1-3, day-of-week Monday
        CronExpression c = CronExpression.parse("*/10 9-10 1,15 1-3 1");
        // Monday 2024-02-05 08:59 -> 09:00 same day (dom doesn't match but dow does)
        ZonedDateTime after = ZonedDateTime.of(2024, 2, 5, 8, 59, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 2, 5, 9, 0, 0, 0, ZoneOffset.UTC), next);
    }

    @Test
    void testSundayAlias7() {
        CronExpression c = CronExpression.parse("0 0 * * 7");
        // Saturday -> next day Sunday at 00:00
        ZonedDateTime after = ZonedDateTime.of(2024, 8, 17, 23, 59, 0, 0, ZoneOffset.UTC); // Saturday
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 8, 18, 0, 0, 0, 0, ZoneOffset.UTC), next);
    }

    @Test
    void testInvalidInputs() {
        // bad field count
        assertThrows(IllegalArgumentException.class, () -> CronExpression.parse("* * * *"));
        // invalid minute
        assertThrows(IllegalArgumentException.class, () -> CronExpression.parse("60 * * * *"));
        // zero step
        assertThrows(IllegalArgumentException.class, () -> CronExpression.parse("*/0 * * * *"));
        // reversed range
        assertThrows(IllegalArgumentException.class, () -> CronExpression.parse("10-5 * * * *"));
    }
}

Notes:
- Day-of-week uses 0=Sunday through 6=Saturday, and 7 is accepted as an alias for Sunday.
- Day-of-month and day-of-week obey OR semantics: a date matches if either the day-of-month matches or the day-of-week matches (alongside minute, hour, month).
- next returns a time strictly after the provided instant and is aligned to minute precision in UTC.

Here’s an updated implementation that:

- Respects the time zone of the ZonedDateTime passed to next (calculations are done in that zone).
- Implements the classic cron rule for day-of-month and day-of-week:
  - If both are restricted (not "*"), a date matches if either matches.
  - If one is "*", only the other is considered.
- Supports names for months (JAN-DEC) and days of week (MON-SUN), case-insensitive, with 7 accepted as Sunday.
- Still supports *, lists, ranges, and steps.

