import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.temporal.ChronoUnit;
import java.util.BitSet;
import java.util.Locale;
import java.util.Objects;

public final class CronExpression {

    private final BitSet minutes;   // 0-59
    private final BitSet hours;     // 0-23
    private final BitSet dom;       // 1-31
    private final BitSet months;    // 1-12
    private final BitSet dows;      // 0-6 (0=Sun .. 6=Sat)

    // For classic cron rule
    private final boolean domIsStar;
    private final boolean dowIsStar;

    private CronExpression(BitSet minutes, BitSet hours, BitSet dom, BitSet months, BitSet dows,
                           boolean domIsStar, boolean dowIsStar) {
        this.minutes = minutes;
        this.hours = hours;
        this.dom = dom;
        this.months = months;
        this.dows = dows;
        this.domIsStar = domIsStar;
        this.dowIsStar = dowIsStar;
    }

    public static CronExpression parse(String expr) {
        Objects.requireNonNull(expr, "expr must not be null");
        String[] parts = expr.trim().split("\\s+");
        if (parts.length != 5) {
            throw new IllegalArgumentException("Invalid cron expression: expected 5 fields but got " + parts.length);
        }

        boolean domIsStar = parts[2].trim().equals("*");
        boolean dowIsStar = parts[4].trim().equals("*");

        BitSet minutes = parseField(parts[0], 0, 59, FieldType.MINUTE);
        BitSet hours = parseField(parts[1], 0, 23, FieldType.HOUR);
        BitSet dom = parseField(parts[2], 1, 31, FieldType.DOM);
        BitSet months = parseField(parts[3], 1, 12, FieldType.MONTH);
        BitSet dows = parseField(parts[4], 0, 7, FieldType.DOW); // allow 7 as Sunday alias

        // Normalize DOW: map 7 -> 0
        if (dows.get(7)) {
            dows.set(0);
            dows.clear(7);
        }

        ensureNonEmpty(minutes, "minute");
        ensureNonEmpty(hours, "hour");
        ensureNonEmpty(dom, "day-of-month");
        ensureNonEmpty(months, "month");
        ensureNonEmpty(dows, "day-of-week");

        return new CronExpression(minutes, hours, dom, months, dows, domIsStar, dowIsStar);
    }

    public ZonedDateTime next(ZonedDateTime after) {
        Objects.requireNonNull(after, "after must not be null");
        ZoneId zone = after.getZone();

        // Work at minute precision, strictly after the instant
        ZonedDateTime t = after.truncatedTo(ChronoUnit.MINUTES).plusMinutes(1);
        ZonedDateTime limit = t.plusYears(10);

        while (!t.isAfter(limit)) {
            // Month check/adjust
            int month = t.getMonthValue();
            if (!months.get(month)) {
                int nextMon = nextOrFirst(months, 1, 12, month);
                if (nextMon > month) {
                    t = t.withMonth(nextMon).withDayOfMonth(1).withHour(0).withMinute(0);
                } else {
                    t = t.plusYears(1).withMonth(nextMon).withDayOfMonth(1).withHour(0).withMinute(0);
                }
                continue;
            }

            // Day check/adjust according to classic cron rule
            if (!dayMatches(t)) {
                t = t.plusDays(1).withHour(0).withMinute(0);
                continue;
            }

            // Hour check/adjust
            int hour = t.getHour();
            if (!hours.get(hour)) {
                int nextHour = nextOrFirst(hours, 0, 23, hour);
                if (nextHour > hour) {
                    t = t.withHour(nextHour).withMinute(0);
                } else {
                    t = t.plusDays(1).withHour(nextHour).withMinute(0);
                }
                continue;
            }

            // Minute check/adjust
            int minute = t.getMinute();
            if (!minutes.get(minute)) {
                int nextMinute = nextOrFirst(minutes, 0, 59, minute);
                if (nextMinute > minute) {
                    t = t.withMinute(nextMinute);
                } else {
                    t = t.plusHours(1).withMinute(nextMinute);
                }
                continue;
            }

            // All fields match
            return t.withZoneSameInstant(zone);
        }

        throw new IllegalStateException("No matching time found within 10 years for cron expression");
    }

    private boolean dayMatches(ZonedDateTime t) {
        int day = t.getDayOfMonth();
        int maxDom = t.toLocalDate().lengthOfMonth();
        boolean domOk = day <= maxDom && dom.get(day);

        int javaDow = t.getDayOfWeek().getValue(); // 1=Mon .. 7=Sun
        int cronDow = javaDow % 7; // 0=Sun, 1=Mon, .., 6=Sat
        boolean dowOk = dows.get(cronDow);

        // Classic cron rule:
        // - If both restricted (not '*'): domOk || dowOk
        // - If one is '*': only the other matters
        if (domIsStar && dowIsStar) {
            return true;
        } else if (domIsStar) {
            return dowOk;
        } else if (dowIsStar) {
            return domOk;
        } else {
            return domOk || dowOk;
        }
    }

    private static int nextOrFirst(BitSet set, int min, int max, int value) {
        int n = set.nextSetBit(value);
        if (n >= min && n <= max) {
            return n;
        }
        int first = set.nextSetBit(min);
        if (first < 0 || first > max) {
            throw new IllegalArgumentException("Empty field set unexpectedly");
        }
        return first;
    }

    private static void ensureNonEmpty(BitSet bs, String fieldName) {
        if (bs.isEmpty()) {
            throw new IllegalArgumentException("No values allowed for field: " + fieldName);
        }
    }

    private enum FieldType { MINUTE, HOUR, DOM, MONTH, DOW }

    private static BitSet parseField(String text, int min, int maxInclusive, FieldType type) {
        BitSet result = new BitSet(maxInclusive + 1);
        String[] items = text.split(",");
        for (String raw : items) {
            String item = raw.trim();
            if (item.isEmpty()) {
                throw new IllegalArgumentException("Empty token in " + fieldName(type) + " field");
            }

            String rangePart = item;
            Integer step = null;

            int slashIdx = item.indexOf('/');
            if (slashIdx >= 0) {
                rangePart = item.substring(0, slashIdx).trim();
                String stepStr = item.substring(slashIdx + 1).trim();
                if (stepStr.isEmpty()) {
                    throw new IllegalArgumentException("Missing step value in " + fieldName(type) + " field: " + item);
                }
                try {
                    step = Integer.parseInt(stepStr);
                } catch (NumberFormatException ex) {
                    throw new IllegalArgumentException("Invalid step '" + stepStr + "' in " + fieldName(type) + " field", ex);
                }
                if (step <= 0) {
                    throw new IllegalArgumentException("Step must be positive in " + fieldName(type) + " field: " + item);
                }
            }

            int from, to;
            if (rangePart.equals("*")) {
                from = min;
                to = maxInclusive;
            } else if (rangePart.contains("-")) {
                String[] ab = rangePart.split("-", 2);
                if (ab.length != 2 || ab[0].isEmpty() || ab[1].isEmpty()) {
                    throw new IllegalArgumentException("Invalid range '" + rangePart + "' in " + fieldName(type) + " field");
                }
                int a = parseValue(type, ab[0], min, maxInclusive);
                int b = parseValue(type, ab[1], min, maxInclusive);
                if (type == FieldType.DOW) {
                    // Allow 7 as Sunday alias; keep range continuity by leaving 7 for now
                    // We'll normalize 7 -> 0 after finishing the field
                }
                if (a > b) {
                    throw new IllegalArgumentException("Range start > end in " + fieldName(type) + " field: " + rangePart);
                }
                from = a;
                to = b;
            } else {
                int n = parseValue(type, rangePart, min, maxInclusive);
                from = n;
                // For n/step form, treat as n..max
                to = (slashIdx >= 0 && !rangePart.equals("*")) ? maxInclusive : n;
            }

            if (step == null) step = 1;

            for (int v = from; v <= to; v += step) {
                result.set(v);
            }
        }

        // Normalize for ranges above bounds (clip) and DOW alias 7 -> 0 later
        result.clear(0, min);
        if (maxInclusive + 1 < result.size()) {
            result.clear(maxInclusive + 1, result.size());
        }

        // For DOW, map bit 7 to 0 alias
        if (type == FieldType.DOW && result.get(7)) {
            result.set(0);
            result.clear(7);
        }

        return result;
    }

    private static int parseValue(FieldType type, String token, int min, int maxInclusive) {
        String field = fieldName(type);
        String t = token.trim();
        if (t.equals("*")) {
            return min; // caller handles as range
        }

        // Try names for MONTH and DOW; support case-insensitive 3-letter names
        if (type == FieldType.MONTH) {
            Integer n = parseMonthName(t);
            if (n != null) return n;
        } else if (type == FieldType.DOW) {
            Integer n = parseDowName(t);
            if (n != null) return n;
        }

        int n;
        try {
            n = Integer.parseInt(t);
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("Invalid token '" + t + "' in " + field + " field", ex);
        }

        // For DOW, allow 7 as Sunday alias
        if (type == FieldType.DOW && n == 7) {
            return 7;
        }

        if (n < min || n > maxInclusive) {
            String range = min + "-" + maxInclusive + (type == FieldType.DOW ? " (7 allowed as Sunday)" : "");
            throw new IllegalArgumentException("Value out of range for " + field + ": " + n + " (allowed " + range + ")");
        }
        return n;
    }

    private static Integer parseMonthName(String token) {
        String s = token.toUpperCase(Locale.ROOT);
        switch (s) {
            case "JAN": return 1;
            case "FEB": return 2;
            case "MAR": return 3;
            case "APR": return 4;
            case "MAY": return 5;
            case "JUN": return 6;
            case "JUL": return 7;
            case "AUG": return 8;
            case "SEP": return 9;
            case "OCT": return 10;
            case "NOV": return 11;
            case "DEC": return 12;
            default: return null;
        }
    }

    // Return 1..7 with SUN=7, MON=1, ... SAT=6; map SUN to 7 so ranges like MON-SUN are 1..7
    private static Integer parseDowName(String token) {
        String s = token.toUpperCase(Locale.ROOT);
        switch (s) {
            case "SUN": return 7; // alias -> normalized later
            case "MON": return 1;
            case "TUE":
            case "TUES":
            case "TUESDAY":
                return 2;
            case "WED":
            case "WEDS":
            case "WEDNESDAY":
                return 3;
            case "THU":
            case "THUR":
            case "THURS":
            case "THURSDAY":
                return 4;
            case "FRI":
                return 5;
            case "SAT":
                return 6;
            default: return null;
        }
    }

    private static String fieldName(FieldType type) {
        switch (type) {
            case MINUTE: return "minute";
            case HOUR: return "hour";
            case DOM: return "day-of-month";
            case MONTH: return "month";
            case DOW: return "day-of-week";
            default: return "field";
        }
    }
}

