import org.junit.jupiter.api.Test;

import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;

import static org.junit.jupiter.api.Assertions.*;

public class CronExpressionTest {

    @Test
    void testEveryMinuteUtc() {
        CronExpression c = CronExpression.parse("* * * * *");
        ZonedDateTime after = ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 1, 1, 0, 1, 0, 0, ZoneOffset.UTC), next);
    }

    @Test
    void testRespectsZoneLisbon() {
        ZoneId lisbon = ZoneId.of("Europe/Lisbon");
        CronExpression c = CronExpression.parse("0 9 * * *"); // 09:00 every day
        ZonedDateTime after = ZonedDateTime.of(2024, 6, 1, 8, 59, 0, 0, lisbon);
        ZonedDateTime next = c.next(after);
        assertEquals(lisbon, next.getZone());
        assertEquals(ZonedDateTime.of(2024, 6, 1, 9, 0, 0, 0, lisbon), next);

        // Strictly after: exactly at 09:00 -> next day 09:00
        ZonedDateTime atFire = ZonedDateTime.of(2024, 6, 1, 9, 0, 0, 0, lisbon);
        ZonedDateTime next2 = c.next(atFire);
        assertEquals(ZonedDateTime.of(2024, 6, 2, 9, 0, 0, 0, lisbon), next2);
    }

    @Test
    void testStepMinutes() {
        CronExpression c = CronExpression.parse("*/15 * * * *");
        ZonedDateTime after = ZonedDateTime.of(2024, 1, 1, 12, 7, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 1, 1, 12, 15, 0, 0, ZoneOffset.UTC), next);

        ZonedDateTime afterExact = ZonedDateTime.of(2024, 1, 1, 12, 0, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next2 = c.next(afterExact);
        assertEquals(ZonedDateTime.of(2024, 1, 1, 12, 15, 0, 0, ZoneOffset.UTC), next2);
    }

    @Test
    void testNewYearMidnight() {
        CronExpression c = CronExpression.parse("0 0 1 JAN *");
        ZonedDateTime after = ZonedDateTime.of(2023, 12, 31, 23, 59, 59, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC), next);

        ZonedDateTime atFire = ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next2 = c.next(atFire);
        assertEquals(ZonedDateTime.of(2025, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC), next2);
    }

    @Test
    void testWeekdaysAtNoonDomStarUsesDowOnly() {
        CronExpression c = CronExpression.parse("0 12 * * MON-FRI"); // dom '*', dow restricted
        ZonedDateTime tueBeforeNoon = ZonedDateTime.of(2024, 8, 13, 11, 59, 0, 0, ZoneOffset.UTC); // Tuesday
        assertEquals(ZonedDateTime.of(2024, 8, 13, 12, 0, 0, 0, ZoneOffset.UTC), c.next(tueBeforeNoon));

        ZonedDateTime satAfterNoon = ZonedDateTime.of(2024, 8, 17, 13, 0, 0, 0, ZoneOffset.UTC); // Saturday
        // Next should be Monday at 12:00
        assertEquals(ZonedDateTime.of(2024, 8, 19, 12, 0, 0, 0, ZoneOffset.UTC), c.next(satAfterNoon));
    }

    @Test
    void testOrSemanticsDomDowBothRestricted() {
        CronExpression c = CronExpression.parse("0 0 13 * MON");
        // Before Monday 2024-08-12 00:00 -> matches Monday 00:00 due to DOW
        ZonedDateTime beforeMonday = ZonedDateTime.of(2024, 8, 11, 23, 59, 0, 0, ZoneOffset.UTC); // Sunday
        assertEquals(ZonedDateTime.of(2024, 8, 12, 0, 0, 0, 0, ZoneOffset.UTC), c.next(beforeMonday));

        // After Monday but before 13th: next is 13th 00:00 due to DOM
        ZonedDateTime afterMonday = ZonedDateTime.of(2024, 8, 12, 12, 0, 0, 0, ZoneOffset.UTC);
        assertEquals(ZonedDateTime.of(2024, 8, 13, 0, 0, 0, 0, ZoneOffset.UTC), c.next(afterMonday));
    }

    @Test
    void testSundayAlias7AndNames() {
        CronExpression c1 = CronExpression.parse("0 0 * * 7"); // Sunday alias
        ZonedDateTime afterSat = ZonedDateTime.of(2024, 8, 17, 23, 59, 0, 0, ZoneOffset.UTC); // Saturday
        assertEquals(ZonedDateTime.of(2024, 8, 18, 0, 0, 0, 0, ZoneOffset.UTC), c1.next(afterSat));

        CronExpression c2 = CronExpression.parse("0 0 1 JAN-MAR MON");
        // Jan 1 2024 is Monday -> strictly after check: start from just before midnight Dec 31
        ZonedDateTime beforeNewYear = ZonedDateTime.of(2023, 12, 31, 23, 59, 59, 0, ZoneOffset.UTC);
        assertEquals(ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC), c2.next(beforeNewYear));
    }

    @Test
    void testFeb29() {
        CronExpression c = CronExpression.parse("0 0 29 FEB *");
        ZonedDateTime after = ZonedDateTime.of(2021, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC);
        ZonedDateTime next = c.next(after);
        assertEquals(ZonedDateTime.of(2024, 2, 29, 0, 0, 0, 0, ZoneOffset.UTC), next);
    }

    @Test
    void testInvalidInputs() {
        assertThrows(IllegalArgumentException.class, () -> CronExpression.parse("* * * *")); // bad field count
        assertThrows(IllegalArgumentException.class, () -> CronExpression.parse("60 * * * *")); // invalid minute
        assertThrows(IllegalArgumentException.class, () -> CronExpression.parse("*/0 * * * *")); // zero step
        assertThrows(IllegalArgumentException.class, () -> CronExpression.parse("10-5 * * * *")); // reversed range

        // Invalid name
        assertThrows(IllegalArgumentException.class, () -> CronExpression.parse("0 0 * FOOBAR *"));
    }
}

Notes:
- Months accept JAN-DEC (case-insensitive). Days-of-week accept MON-SUN (case-insensitive). For DOW, 0=Sunday and 7 is accepted as an alias for Sunday; ranges like MON-SUN are interpreted as 1-7 and normalized internally.
- Day-of-month and day-of-week obey the classic rule: if both fields are restricted (not "*"), a date matches if either matches. If one is "*", only the other is considered.
- next respects the zone of the ZonedDateTime argument. Calculations occur in that zone.

Below is an updated, self-contained implementation with DST-aware behavior matching Vixie cron/cronie semantics, plus a JUnit 5 test suite.

Key points:
- Respects the time zone of the provided ZonedDateTime.
- Classic cron DOM/DOW rule: if both are restricted (not "*"), a date matches if either matches. If one is "*", only the other is considered.
- Supports month/day names (JAN-DEC, MON-SUN), case-insensitive. DOW accepts 7 as Sunday alias.
- DST semantics:
  - Fixed-time jobs (minute/hour are plain numbers and/or lists, no *, no ranges, no steps): 
    - Spring-forward gap: run once at the transition instant (first valid instant after the gap).
    - Fall-back overlap: run only once, on the first occurrence (earlier offset).
  - Wildcard/step jobs (*, ranges, steps): elapsed-time based. They fire at each actually-occurring matching minute. In fall-back overlap they fire in both passes; in a spring-forward gap, missing minutes simply don’t exist.
- Adds nextN(after, n) to fetch the next n run times strictly after the given instant.

