import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZoneOffsetTransition;
import java.time.ZonedDateTime;
import java.time.temporal.ChronoUnit;
import java.time.zone.ZoneRules;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.List;
import java.util.Locale;
import java.util.Objects;

public final class CronExpression {

    private final BitSet minutes;   // 0-59
    private final BitSet hours;     // 0-23
    private final BitSet dom;       // 1-31
    private final BitSet months;    // 1-12
    private final BitSet dows;      // 0-6 (0=Sun .. 6=Sat)

    // For classic cron rule
    private final boolean domIsStar;
    private final boolean dowIsStar;

    // DST behavior: fixed-time if minute/hour are plain numeric lists (no *, no -, no /)
    private final boolean fixedTime;

    private CronExpression(BitSet minutes, BitSet hours, BitSet dom, BitSet months, BitSet dows,
                           boolean domIsStar, boolean dowIsStar,
                           boolean fixedTime) {
        this.minutes = minutes;
        this.hours = hours;
        this.dom = dom;
        this.months = months;
        this.dows = dows;
        this.domIsStar = domIsStar;
        this.dowIsStar = dowIsStar;
        this.fixedTime = fixedTime;
    }

    public static CronExpression parse(String expr) {
        Objects.requireNonNull(expr, "expr must not be null");
        String[] parts = expr.trim().split("\\s+");
        if (parts.length != 5) {
            throw new IllegalArgumentException("Invalid cron expression: expected 5 fields but got " + parts.length);
        }

        boolean domIsStar = parts[2].trim().equals("*");
        boolean dowIsStar = parts[4].trim().equals("*");

        // Detect "plain" minute/hour (numbers and/or comma lists only)
        boolean minutePlain = isPlainNumberList(parts[0]);
        boolean hourPlain = isPlainNumberList(parts[1]);
        boolean fixedTime = minutePlain && hourPlain;

        BitSet minutes = parseField(parts[0], 0, 59, FieldType.MINUTE);
        BitSet hours = parseField(parts[1], 0, 23, FieldType.HOUR);
        BitSet dom = parseField(parts[2], 1, 31, FieldType.DOM);
        BitSet months = parseField(parts[3], 1, 12, FieldType.MONTH);
        BitSet dows = parseField(parts[4], 0, 7, FieldType.DOW); // allow 7 as Sunday alias

        // Normalize DOW: map 7 -> 0
        if (dows.get(7)) {
            dows.set(0);
            dows.clear(7);
        }

        ensureNonEmpty(minutes, "minute");
        ensureNonEmpty(hours, "hour");
        ensureNonEmpty(dom, "day-of-month");
        ensureNonEmpty(months, "month");
        ensureNonEmpty(dows, "day-of-week");

        return new CronExpression(minutes, hours, dom, months, dows, domIsStar, dowIsStar, fixedTime);
    }

    public ZonedDateTime next(ZonedDateTime after) {
        Objects.requireNonNull(after, "after must not be null");
        if (fixedTime) {
            return nextFixed(after);
        } else {
            return nextElapsed(after);
        }
    }

    public List<ZonedDateTime> nextN(ZonedDateTime after, int n) {
        if (n <= 0) throw new IllegalArgumentException("n must be > 0");
        List<ZonedDateTime> res = new ArrayList<>(n);
        ZonedDateTime cur = after;
        for (int i = 0; i < n; i++) {
            ZonedDateTime nx = next(cur);
            res.add(nx);
            cur = nx; // strictly after next run
        }
        return res;
    }

    // Elapsed-time based (wildcards/steps/ranges present)
    // Scan minute-by-minute along the timeline; picks both passes in overlaps and skips missing minutes.
    private ZonedDateTime nextElapsed(ZonedDateTime after) {
        ZoneId zone = after.getZone();
        ZonedDateTime t = after.truncatedTo(ChronoUnit.MINUTES).plusMinutes(1);
        ZonedDateTime limit = t.plusYears(10);

        while (!t.isAfter(limit)) {
            if (!months.get(t.getMonthValue())) {
                t = t.plusMinutes(1);
                continue;
            }
            if (!dayMatches(t)) {
                t = t.plusMinutes(1);
                continue;
            }
            if (!hours.get(t.getHour())) {
                t = t.plusMinutes(1);
                continue;
            }
            if (!minutes.get(t.getMinute())) {
                t = t.plusMinutes(1);
                continue;
            }
            return t.withZoneSameInstant(zone);
        }
        throw new IllegalStateException("No matching time found within 10 years for cron expression");
    }

    // Fixed-time semantics (minute/hour are plain numeric lists)
    // For each matching day, schedule each (hour,minute) in order:
    // - If LDT is valid: run at that exact time (if strictly after).
    // - If gap: run once at transition instant (first valid instant after the gap).
    // - If overlap: run only once at the first occurrence (earlier offset).
    private ZonedDateTime nextFixed(ZonedDateTime after) {
        ZoneId zone = after.getZone();
        ZonedDateTime start = after.truncatedTo(ChronoUnit.MINUTES).plusMinutes(1);
        LocalDate d = start.toLocalDate();
        ZonedDateTime limit = start.plusYears(10);

        while (!start.isAfter(limit)) {
            // Ensure month allowed; if not, move to first day of next allowed month
            if (!months.get(d.getMonthValue())) {
                // Advance to next allowed month
                int m = d.getMonthValue();
                int nextM = nextAllowed(months, 1, 12, m);
                if (nextM > m) {
                    d = LocalDate.of(d.getYear(), nextM, 1);
                } else {
                    d = LocalDate.of(d.getYear() + 1, nextM, 1);
                }
                // Reset start-of-day
                start = ZonedDateTime.of(d, java.time.LocalTime.MIDNIGHT, zone);
                continue;
            }

            // Day-of-month/day-of-week rule
            ZonedDateTime dayStart = ZonedDateTime.of(d, java.time.LocalTime.MIDNIGHT, zone);
            if (!dayMatches(dayStart)) {
                d = d.plusDays(1);
                if (d.getDayOfMonth() == 1 && !months.get(d.getMonthValue())) {
                    // handled at top on next iteration
                }
                continue;
            }

            // Generate candidate times (hour, minute) in ascending order
            // If day equals start date, enforce strictly-after time-of-day
            boolean sameDay = d.equals(start.toLocalDate());
            int startHour = sameDay ? start.getHour() : -1;
            int startMinute = sameDay ? start.getMinute() : -1;

            for (int h = hours.nextSetBit(0); h >= 0; h = hours.nextSetBit(h + 1)) {
                for (int m = minutes.nextSetBit(0); m >= 0; m = minutes.nextSetBit(m + 1)) {
                    if (sameDay) {
                        if (h < startHour) continue;
                        if (h == startHour && m <= startMinute) continue; // strictly after
                    }
                    LocalDateTime ldt = LocalDateTime.of(d.getYear(), d.getMonth(), d.getDayOfMonth(), h, m);
                    ZonedDateTime candidate = resolveFixed(zone, ldt);
                    if (candidate.isAfter(start)) {
                        return candidate;
                    }
                }
            }

            // Move to next day
            d = d.plusDays(1);
            start = ZonedDateTime.of(d, java.time.LocalTime.MIDNIGHT, zone);
        }

        throw new IllegalStateException("No matching time found within 10 years for cron expression");
    }

    // Resolve fixed-time LDT with DST rules:
    // - Valid -> exact instant
    // - Gap -> transition instant (first valid instant after gap)
    // - Overlap -> first occurrence (earlier offset)
    private static ZonedDateTime resolveFixed(ZoneId zone, LocalDateTime ldt) {
        ZoneRules rules = zone.getRules();
        List<ZoneOffset> valid = rules.getValidOffsets(ldt);
        if (valid.size() == 1) {
            return ZonedDateTime.of(ldt, zone);
        } else if (valid.isEmpty()) {
            ZoneOffsetTransition tr = rules.getTransition(ldt);
            if (tr == null || !tr.isGap()) {
                throw new IllegalStateException("Expected gap transition for " + ldt + " in " + zone);
            }
            // First valid instant after gap:
            LocalDateTime after = tr.getDateTimeAfter();
            return ZonedDateTime.of(after, zone);
        } else {
            // Overlap: choose earlier offset (first occurrence)
            ZoneOffsetTransition tr = rules.getTransition(ldt);
            if (tr == null || !tr.isOverlap()) {
                // Fallback to earlier offset if transition not accessible
                ZoneOffset earlier = valid.get(0);
                // ZonedDateTime.ofLocal prefers earlier if preferred is null
                return ZonedDateTime.ofLocal(ldt, zone, earlier);
            }
            ZoneOffset earlier = tr.getOffsetBefore();
            return ZonedDateTime.ofLocal(ldt, zone, earlier);
        }
    }

    private boolean dayMatches(ZonedDateTime t) {
        int day = t.getDayOfMonth();
        int maxDom = t.toLocalDate().lengthOfMonth();
        boolean domOk = day <= maxDom && dom.get(day);

        int javaDow = t.getDayOfWeek().getValue(); // 1=Mon .. 7=Sun
        int cronDow = javaDow % 7; // 0=Sun, 1=Mon, .., 6=Sat
        boolean dowOk = dows.get(cronDow);

        // Classic cron rule:
        // - If both restricted (not '*'): domOk || dowOk
        // - If one is '*': only the other matters
        if (domIsStar && dowIsStar) {
            return true;
        } else if (domIsStar) {
            return dowOk;
        } else if (dowIsStar) {
            return domOk;
        } else {
            return domOk || dowOk;
        }
    }

    private static int nextAllowed(BitSet set, int min, int max, int current) {
        int n = set.nextSetBit(current);
        if (n >= min && n <= max) {
            return n;
        }
        int first = set.nextSetBit(min);
        if (first < 0 || first > max) {
            throw new IllegalArgumentException("Empty field set unexpectedly");
        }
        return first;
    }

    private static void ensureNonEmpty(BitSet bs, String fieldName) {
        if (bs.isEmpty()) {
            throw new IllegalArgumentException("No values allowed for field: " + fieldName);
        }
    }

    private enum FieldType { MINUTE, HOUR, DOM, MONTH, DOW }

    private static BitSet parseField(String text, int min, int maxInclusive, FieldType type) {
        BitSet result = new BitSet(maxInclusive + 1);
        String[] items = text.split(",");
        for (String raw : items) {
            String item = raw.trim();
            if (item.isEmpty()) {
                throw new IllegalArgumentException("Empty token in " + fieldName(type) + " field");
            }

            String rangePart = item;
            Integer step = null;

            int slashIdx = item.indexOf('/');
            if (slashIdx >= 0) {
                rangePart = item.substring(0, slashIdx).trim();
                String stepStr = item.substring(slashIdx + 1).trim();
                if (stepStr.isEmpty()) {
                    throw new IllegalArgumentException("Missing step value in " + fieldName(type) + " field: " + item);
                }
                try {
                    step = Integer.parseInt(stepStr);
                } catch (NumberFormatException ex) {
                    throw new IllegalArgumentException("Invalid step '" + stepStr + "' in " + fieldName(type) + " field", ex);
                }
                if (step <= 0) {
                    throw new IllegalArgumentException("Step must be positive in " + fieldName(type) + " field: " + item);
                }
            }

            int from, to;
            if (rangePart.equals("*")) {
                from = min;
                to = maxInclusive;
            } else if (rangePart.contains("-")) {
                String[] ab = rangePart.split("-", 2);
                if (ab.length != 2 || ab[0].isEmpty() || ab[1].isEmpty()) {
                    throw new IllegalArgumentException("Invalid range '" + rangePart + "' in " + fieldName(type) + " field");
                }
                int a = parseValue(type, ab[0], min, maxInclusive);
                int b = parseValue(type, ab[1], min, maxInclusive);
                if (a > b) {
                    throw new IllegalArgumentException("Range start > end in " + fieldName(type) + " field: " + rangePart);
                }
                from = a;
                to = b;
            } else {
                int n = parseValue(type, rangePart, min, maxInclusive);
                from = n;
                to = (slashIdx >= 0 && !rangePart.equals("*")) ? maxInclusive : n;
            }

            if (step == null) step = 1;

            for (int v = from; v <= to; v += step) {
                result.set(v);
            }
        }

        // Clip and normalize
        result.clear(0, min);
        if (maxInclusive + 1 < result.size()) {
            result.clear(maxInclusive + 1, result.size());
        }

        // For DOW, map bit 7 to 0 alias
        if (type == FieldType.DOW && result.get(7)) {
            result.set(0);
            result.clear(7);
        }

        return result;
    }

    private static int parseValue(FieldType type, String token, int min, int maxInclusive) {
        String field = fieldName(type);
        String t = token.trim();
        if (t.equals("*")) {
            return min; // caller handles as range
        }

        // Try names for MONTH and DOW; support case-insensitive names
        if (type == FieldType.MONTH) {
            Integer n = parseMonthName(t);
            if (n != null) return n;
        } else if (type == FieldType.DOW) {
            Integer n = parseDowName(t);
            if (n != null) return n;
        }

        int n;
        try {
            n = Integer.parseInt(t);
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("Invalid token '" + t + "' in " + field + " field", ex);
        }

        // For DOW, allow 7 as Sunday alias
        if (type == FieldType.DOW && n == 7) {
            return 7;
        }

        if (n < min || n > maxInclusive) {
            String range = min + "-" + maxInclusive + (type == FieldType.DOW ? " (7 allowed as Sunday)" : "");
            throw new IllegalArgumentException("Value out of range for " + field + ": " + n + " (allowed " + range + ")");
        }
        return n;
    }

    private static Integer parseMonthName(String token) {
        String s = token.toUpperCase(Locale.ROOT);
        switch (s) {
            case "JAN": return 1;
            case "FEB": return 2;
            case "MAR": return 3;
            case "APR": return 4;
            case "MAY": return 5;
            case "JUN": return 6;
            case "JUL": return 7;
            case "AUG": return 8;
            case "SEP": return 9;
            case "OCT": return 10;
            case "NOV": return 11;
            case "DEC": return 12;
            default: return null;
        }
    }

    // Returns 1..7 for MON..SUN with SUN=7 (normalized later to 0)
    private static Integer parseDowName(String token) {
        String s = token.toUpperCase(Locale.ROOT);
        switch (s) {
            case "SUN": return 7; // normalized later
            case "MON": return 1;
            case "TUE":
            case "TUES":
            case "TUESDAY": return 2;
            case "WED":
            case "WEDS":
            case "WEDNESDAY": return 3;
            case "THU":
            case "THUR":
            case "THURS":
            case "THURSDAY": return 4;
            case "FRI": return 5;
            case "SAT": return 6;
            default: return null;
        }
    }

    private static boolean isPlainNumberList(String text) {
        String[] items = text.split(",");
        if (items.length == 0) return false;
        for (String raw : items) {
            String s = raw.trim();
            if (s.isEmpty()) return false;
            if (s.equals("*")) return false;
            if (s.contains("-") || s.contains("/") ) return false;
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c < '0' || c > '9') return false;
            }
        }
        return true;
    }

    private static String fieldName(FieldType type) {
        switch (type) {
            case MINUTE: return "minute";
            case HOUR: return "hour";
            case DOM: return "day-of-month";
            case MONTH: return "month";
            case DOW: return "day-of-week";
            default: return "field";
        }
    }
}

