    @Test
    void testLisbonSpringForwardFixed() {
        ZoneId lisbon = ZoneId.of("Europe/Lisbon");
        // DST starts 2026-03-29 (spring forward). 01:00 -> 02:00, hour 01:00 is missing.
        CronExpression at130 = CronExpression.parse("30 1 * * *"); // 01:30
        CronExpression at230 = CronExpression.parse("30 2 * * *"); // 02:30

        ZonedDateTime after = ZonedDateTime.of(2026, 3, 29, 0, 59, 0, 0, lisbon);
        // 01:30 is in the gap -> run once at transition instant (02:00 local)
        assertEquals(ZonedDateTime.of(2026, 3, 29, 2, 0, 0, 0, lisbon), at130.next(after));
        // 02:30 exists -> run at 02:30
        assertEquals(ZonedDateTime.of(2026, 3, 29, 2, 30, 0, 0, lisbon), at230.next(after));
    }

    @Test
    void testLisbonFallBackFixed() {
        ZoneId lisbon = ZoneId.of("Europe/Lisbon");
        // DST ends 2026-10-25 (fall back). 02:00 -> 01:00, hour 01:00 repeats.
        CronExpression at130 = CronExpression.parse("30 1 * * *"); // 01:30

        ZonedDateTime after = ZonedDateTime.of(2026, 10, 25, 0, 59, 0, 0, lisbon);

        // First occurrence of 01:30 (earlier offset)
        ZonedDateTime first0130 = ZonedDateTime.of(2026, 10, 25, 1, 30, 0, 0, lisbon);
        ZonedDateTime next = at130.next(after);
        assertEquals(first0130, next);

        // Next day for the same fixed time (no second occurrence same day)
        ZonedDateTime next2 = at130.next(next);
        ZonedDateTime expectedNextDay = ZonedDateTime.of(2026, 10, 26, 1, 30, 0, 0, lisbon);
        assertEquals(expectedNextDay, next2);
    }

    @Test
    void testLisbonSpringForwardElapsed() {
        ZoneId lisbon = ZoneId.of("Europe/Lisbon");
        // Elapsed-time: 0 * * * * (top of hour)
        CronExpression hourlyTop = CronExpression.parse("0 * * * *");
        // Elapsed-time: */30 * * * * (0 and 30 each hour)
        CronExpression halfHourly = CronExpression.parse("*/30 * * * *");

        ZonedDateTime after = ZonedDateTime.of(2026, 3, 29, 0, 59, 0, 0, lisbon);

        // 01:00 doesn't exist; next is 02:00, then 03:00
        List<ZonedDateTime> top2 = hourlyTop.nextN(after, 2);
        assertEquals(ZonedDateTime.of(2026, 3, 29, 2, 0, 0, 0, lisbon), top2.get(0));
        assertEquals(ZonedDateTime.of(2026, 3, 29, 3, 0, 0, 0, lisbon), top2.get(1));

        // */30: from 00:59 -> 02:00, 02:30, 03:00
        List<ZonedDateTime> next3 = halfHourly.nextN(after, 3);
        assertEquals(ZonedDateTime.of(2026, 3, 29, 2, 0, 0, 0, lisbon), next3.get(0));
        assertEquals(ZonedDateTime.of(2026, 3, 29, 2, 30, 0, 0, lisbon), next3.get(1));
        assertEquals(ZonedDateTime.of(2026, 3, 29, 3, 0, 0, 0, lisbon), next3.get(2));
    }

    @Test
    void testLisbonFallBackElapsed() {
        ZoneId lisbon = ZoneId.of("Europe/Lisbon");
        CronExpression hourlyTop = CronExpression.parse("0 * * * *");
        CronExpression halfHourly = CronExpression.parse("*/30 * * * *");

        ZonedDateTime after = ZonedDateTime.of(2026, 10, 25, 0, 59, 0, 0, lisbon);

        // Expected: 01:00 first pass, 01:00 second pass, then 02:00
        List<ZonedDateTime> next3 = hourlyTop.nextN(after, 3);
        ZonedDateTime first0100 = ZonedDateTime.of(2026, 10, 25, 1, 0, 0, 0, lisbon);
        ZonedDateTime second0100 = first0100.withLaterOffsetAtOverlap();
        assertEquals(first0100, next3.get(0));
        assertEquals(second0100, next3.get(1));
        assertEquals(ZonedDateTime.of(2026, 10, 25, 2, 0, 0, 0, lisbon), next3.get(2));

        // */30: 01:00 (first), 01:30 (first), 01:00 (second), 01:30 (second), 02:00
        List<ZonedDateTime> next5 = halfHourly.nextN(after, 5);
        ZonedDateTime first0130 = ZonedDateTime.of(2026, 10, 25, 1, 30, 0, 0, lisbon);
        ZonedDateTime second0130 = first0130.withLaterOffsetAtOverlap();
        assertEquals(first0100, next5.get(0));
        assertEquals(first0130, next5.get(1));
        assertEquals(second0100, next5.get(2));
        assertEquals(second0130, next5.get(3));
        assertEquals(ZonedDateTime.of(2026, 10, 25, 2, 0, 0, 0, lisbon), next5.get(4));
    }

